const MAX_TILT = 16;
const HOVER_SCALE = 1.03;
const HOLO_REST = 0.12;

const CARD_W = "min(480px, calc(100vw - 32px))";
const mm = (n: number) => `calc(${n} * var(--mm))`;
const NAVY = "#0B1B33";
const BLUE = "#387FD9";
const MUTED = "#5B6B82";

const glare: CSSProperties = {
  backgroundImage:
    "radial-gradient(farthest-corner circle at var(--mx) var(--my), rgba(255,255,255,.28) 0%, rgba(255,255,255,.06) 30%, transparent 60%)",
  opacity: "calc(var(--holo) * var(--fx))",
};

function Face({
  back,
  effect,
  opacity,
  className,
  children,
}: {
  back?: boolean;
  effect: CardEffect;
  opacity: MotionValue<number>;
  className?: string;
  children: ReactNode;
}) {
  return (
    <motion.span
      className={cn("bc-face", className)}
      style={
        {
          transform: back ? "rotateY(180deg)" : "translateZ(0)",
          opacity,
        } as never
      }
    >
      {children}
      <span
        aria-hidden
        style={{
          position: "absolute",
          inset: 0,
          pointerEvents: "none",
          opacity: `calc(var(--holo) * var(--fx) * ${FOIL[effect].k})`,
          ...(FOIL[effect].spot && spot),
        }}
      >
        <span
          style={{
            position: "absolute",
            inset: 0,
            ...FOIL[effect].layer,
          }}
        />
      </span>
      <span
        aria-hidden
        style={{
          position: "absolute",
          inset: 0,
          pointerEvents: "none",
          ...glare,
        }}
      />
    </motion.span>
  );
}

