export function BusinessCard({
  effect = "shards",
  intensity = 0.25,
  idleGlow = HOLO_REST,
  defaultFlipped = false,
  className,
  greeting,
  title,
  subtitle,
  location,
  websiteUrl,
  websiteLabel,
  name,
  nameJp,
  tagline,
  taglineJp,
  email,
  qrCaption,
  qrCaptionJp,
}: {
  effect?: CardEffect;
  intensity?: number;
  idleGlow?: number;
  defaultFlipped?: boolean;
  className?: string;
  greeting?: string;
  title?: string;
  subtitle?: string;
  location?: string;
  websiteUrl?: string | null;
  websiteLabel?: string;
  name?: string;
  nameJp?: string;
  tagline?: string;
  taglineJp?: string;
  email?: string;
  qrCaption?: string;
  qrCaptionJp?: string;
}) {
  const reduceMotion = useReducedMotion();
  const [flipped, setFlipped] = useState(defaultFlipped);

  const px = useMotionValue(0.5);
  const py = useMotionValue(0.5);
  const spring = { stiffness: 180, damping: 18, mass: 0.6 };
  const sx = useSpring(px, spring);
  const sy = useSpring(py, spring);
  const holo = useSpring(idleGlow, { stiffness: 120, damping: 20 });
  const scale = useSpring(1, spring);

  const rotateY = useTransform(sx, [0, 1], [-MAX_TILT, MAX_TILT]);
  const rotateX = useTransform(sy, [0, 1], [MAX_TILT, -MAX_TILT]);
  const mx = useTransform(sx, (v) => `${v * 100}%`);
  const my = useTransform(sy, (v) => `${v * 100}%`);

  const flip = useSpring(defaultFlipped ? 180 : 0, { stiffness: 140, damping: 18 });
  const frontOpacity = useTransform(flip, (a): number => (a < 90 ? 1 : 0));
  const backOpacity = useTransform(flip, (a): number => (a < 90 ? 0 : 1));

  const toggle = () => {
    const next = flip.get() < 90 ? 180 : 0;
    if (reduceMotion) flip.jump(next);
    else flip.set(next);
    setFlipped(next === 180);
  };

  const track = (e: React.PointerEvent<HTMLDivElement>) => {
    const r = e.currentTarget.getBoundingClientRect();
    px.set(Math.min(1, Math.max(0, (e.clientX - r.left) / r.width)));
    py.set(Math.min(1, Math.max(0, (e.clientY - r.top) / r.height)));
    holo.set(1);
    scale.set(HOVER_SCALE);
  };

  const reset = () => {
    px.set(0.5);
    py.set(0.5);
    holo.set(idleGlow);
    scale.set(1);
  };

  const ownerLabel = name || title || "Jason Istioso";

  return (
    <>
      <style>{FONT_CSS}</style>
      <div
        className={cn("bc-root", className)}
        style={
          {
            width: CARD_W,
            maxWidth: "100%",
            "--mm": `calc(${CARD_W} / 91)`,
            perspective: 1200,
          } as CSSProperties
        }
        onPointerDown={track}
        onPointerMove={track}
        onPointerLeave={reset}
        onPointerCancel={reset}
      >
        <motion.button
          type="button"
          aria-label={
            flipped
              ? `Kartu Nama Holografik ${ownerLabel}: klik untuk kembali ke tampak depan.`
              : `Kartu Nama Holografik ${ownerLabel}: klik atau tap untuk melihat detail.`
          }
          className="bc-btn"
          onClick={toggle}
          onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === " ") {
              e.preventDefault();
              toggle();
            }
          }}
          style={
            {
              rotateX: reduceMotion ? 0 : rotateX,
              rotateY: reduceMotion ? 0 : rotateY,
              scale: reduceMotion ? 1 : scale,
              transformStyle: "preserve-3d",
              "--px": sx,
              "--py": sy,
              "--mx": mx,
              "--my": my,
              "--holo": holo,
              "--fx": Math.sqrt(Math.min(1, Math.max(0, intensity))),
            } as never
          }
        >
          <motion.span
            className="bc-flip-shell"
            style={{ rotateY: flip }}
          >
            <Face effect={effect} opacity={frontOpacity}>
              <Front
                greeting={greeting}
                title={title}
                subtitle={subtitle}
                location={location}
                websiteUrl={websiteUrl}
                websiteLabel={websiteLabel}
              />
            </Face>
            <Face back effect={effect} opacity={backOpacity}>
              <Back
                name={name}
                nameJp={nameJp}
                tagline={tagline}
                taglineJp={taglineJp}
                websiteUrl={websiteUrl}
                websiteLabel={websiteLabel}
                email={email}
                qrCaption={qrCaption}
                qrCaptionJp={qrCaptionJp}
              />
            </Face>
          </motion.span>
        </motion.button>
      </div>
    </>
  );
}

export default BusinessCard;
